        self.val = val
        self.left = left
        self.right = right

class Solution:
    def sumOfLeftLeaves(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0
        sum_left_leaves = 0
        queue = deque([root])
        while queue:
            node = queue.popleft()
            if node.left:
                if not node.left.left and not node.left.right:
                    sum_left_leaves += node.left.val
                else:
                    queue.append(node.left)
            if node.right:
                queue.append(node.right)
        return sum_left_leaves

