console.log("Inserting 3, 1, 6, 5, 2, 4 into MinHeap:");
[3, 1, 6, 5, 2, 4].forEach(v => heap.insert(v));

const result = [];
while (!heap.isEmpty()) {
    result.push(heap.extractMin());
}
console.log("Extracted order:", result.join(" "));

