    print("Union(0, 2):", dsu.union(0, 2))
    print("Union(4, 2):", dsu.union(4, 2))
    print("Union(3, 1):", dsu.union(3, 1))

    print("Find(4) == Find(0):", dsu.find(4) == dsu.find(0)) # True
